MAP
    NAME "SS_MAP_GRAL_DELEGACIONES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_delegaciones.log"
    DEBUG 0
    LAYER
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_GRAL_DELEGACIONES"
        METADATA
            'ows_title' 'Delegaciones'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
        END #METADATA
        INCLUDE 'includes/conexion.map'
        DATA "geometry from delegacion using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        CLASSITEM  'gid'
        #INICIA POLIGONO CERRITO DE JEREZ		    
        CLASS
            NAME 'CERRITO DE JEREZ'
            EXPRESSION '1'
            TEXT 'CERRITO DE JEREZ'
            MINSCALE 1000
            MAXSCALE 150000
            LABEL	
                TYPE TRUETYPE 
                FONT 'arial'
                SIZE 16
                PARTIALS FALSE
                MINDISTANCE 800
                BUFFER  300
                POSITION CC
                COLOR 000 000 000
            END	#LABEL
            STYLE
                WIDTH 8
                COLOR 246 239 090
                OUTLINECOLOR 246 239 090
            END #STYLE
        END #CLASS  
        #INICIA POLIGONO LAS JOYAS			 
        CLASS
